    \bs{G}_{N_{\rm g}}(\bs{x})\bs{u}

\dot{\thetahat}
=
\bs{q}(\thetahat, \mathcal{H}_{t}, t).

 \big \| {
 \varphibtrue{\tau}{\bs{x}} - \varphibhat{\tau}{\bs{x}}
 } \big \|
\leq \delta_{\varphi}(\tau,\bs{x},t),

   \delta_{\varphi}(\tau,\bs{x},t) & \defeq
    \int_0^{\tau} {\rm e}^{L_{\rm b}(\tau-s)}
    d_{\rm b}(s,\bs{x},t) ~\!d s, \\
% \end{equation}
