\sum_{i=1}^{N}
\norm{
    \bs{\psi}_{{\rm b},i}
    \big(\varphibhat{\tau}{\bs{x}}\big)
}_{\rm s} 
\rho_i(t) = d_{\rm b}(\tau,\bs{x},t).

\norm{\bs{e}(\tau,\bs{x},t)}
