\int_0^{\tau} \!\!
\norm{
\bs{f}_{\rm b}
\big(\varphibtrue{s}{\bs{x}},\bs{\theta}\big)
\!-\!
\bs{f}_{\rm b}
\big(\varphibhat{s}{\bs{x}},\bs{\theta}\big)
} d s
\\
& \quad +
\int_0^{\tau}
\norm{
\bs{\psi}_{\rm b}
\big(\varphibhat{s}{\bs{x}}\big)
\thetatilde(t)
} d s,
\\
& \leq
\int_0^{\tau}
\big(
L_{\rm b}
\norm{\bs{e}(s,\bs{x},t)}
+
d_{\rm b}(s,\bs{x},t)
\big) d s,

a(\tau,\bs{x},\bs{u},t)
 +
 \inf_{\bs{\eta}\in\Thetatilde}
 \bs{c}(\tau,\bs{x},\bs{u},t)^{\top}\bs{\eta}
