 \\
 a_{\rm b}(\bs{x},\bs{u},t)
 +
 \inf_{\bs{\eta}\in\Thetatilde}
 \bs{c}_{\rm b}(\bs{x},\bs{u},t)^{\top}\bs{\eta}
 & \geq
 0.

   & a(\tau,\bs{x},\bs{u},t)
